#include <bits/stdc++.h>
using namespace std;
const string W="LLLLRLRRRRLRLLRRLLLLRRLLRRRRLLRRLRLLRLLRLRLLRRRRLLRLLRRRRLLRRRRLLRLRRRRLRLLLLRRRRLRRLRRRRLLLLRLRRRRLRRRR";
array<bool,1024>legal{};map<int,string>marks;map<pair<int,int>,char>L;const int dx[4]={0,1,0,-1},dy[4]={1,0,-1,0};set<int> patterns;int limit=500,minstop=0,maximum=0;unsigned long long nodes=0,cap=100000000,frontier=0,hits=0;bool stop=false;set<tuple<string,string,string>>returns;string startmark;
void dfs(string&w,int x,int y,int h,int bits,bool prevbad){if(++nodes>cap){stop=true;return;}maximum=max(maximum,(int)w.size());if((int)w.size()>=limit){frontier++;return;}pair<int,int>p={x,y};auto it=L.find(p);char old=it==L.end()?'?':it->second;for(char c:{'L','R'}){if(c==old)continue;int nb=((bits<<1)+(c=='R'))&4095;bool bad=w.size()>=9&&!legal[nb&1023];if(bad&&prevbad&&!patterns.count(nb&2047))continue;L[p]=c;w.push_back(c);int hh=(h+(c=='R'?1:3))%4;if((int)w.size()>=12&&(int)w.size()>minstop&&marks.count(nb)){hits++;if(!startmark.empty())returns.insert({startmark,marks[nb],w.substr(0,w.size()-12)});}else dfs(w,x+dx[hh],y+dy[hh],hh,nb,bad);w.pop_back();if(old=='?')L.erase(p);else L[p]=old;if(stop)return;}}
bool seed(string s,int&x,int&y,int&h,int&bits,bool&prev){x=y=h=bits=0;prev=false;for(int i=0;i<(int)s.size();i++){char c=s[i];pair<int,int>p={x,y};if(L.count(p)&&L[p]==c)return false;int nb=((bits<<1)+(c=='R'))&4095;bool bad=i>=9&&!legal[nb&1023];if(bad&&prev&&!patterns.count(nb&2047))return false;L[p]=c;bits=nb;prev=bad;h=(h+(c=='R'?1:3))%4;x+=dx[h];y+=dy[h];}return true;}
int main(int argc,char**argv){string spec=argv[1],prefix=argv[2];vector<string>ms={"LLLLRLRRRRLR","RRRLLRLLRRRR"};stringstream ss(spec);string p;while(getline(ss,p,',')){int pat=0;for(char c:p)pat=(pat<<1)+(c=='R');patterns.insert(pat);ms.push_back("L"+p);ms.push_back("R"+p);}for(string m:ms){int b=0;for(char c:m)b=(b<<1)+(c=='R');marks[b]=m;}for(int i=0;i<104;i++){int b=0;for(char c:(W+W).substr(i,10))b=(b<<1)+(c=='R');legal[b]=true;}string w;dfs(w,0,0,0,0,false);cout<<"initial nodes="<<nodes<<" cap="<<stop<<" frontier="<<frontier<<" max_unmarked="<<maximum<<" first_hits="<<hits<<endl;if(stop||frontier)return 1;for(auto [b,m]:marks){L.clear();int x,y,h,bits;bool prev;if(!seed(m,x,y,h,bits,prev))continue;startmark=m;minstop=12;w=m;dfs(w,x,y,h,bits,prev);}ofstream f(prefix+".returns.tsv");for(auto [a,b,w]:returns)f<<a<<' '<<b<<' '<<w<<'\n';cout<<"total nodes="<<nodes<<" cap="<<stop<<" frontier="<<frontier<<" max_unmarked="<<maximum<<" raw_return_types="<<returns.size()<<endl;return stop||frontier?1:0;}
